{
  "primary_meaning": "Jesus Christ as the Sun of Righteousness (divine light, glory, and healing presence)",
  "primary_basis": [
    "Malachi 4:2",
    "Psalm 84:11",
    "Revelation 1:16",
    "Matthew 17:2",
    "Psalm 19:4-6"
  ],
  "alternatives": [
    {
      "meaning": "God's glory, protective presence, or everlasting light (sometimes overlapping with Christ)",
      "basis": [
        "Psalm 84:11",
        "Isaiah 60:19-20",
        "Revelation 21:23"
      ],
      "prominence": "common"
    },
    {
      "meaning": "The Church, Israel, or Mary (as the woman clothed with the sun)",
      "basis": [
        "Revelation 12:1"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Apocalyptic judgment or cosmic upheaval (via darkening or scorching of the sun)",
      "basis": [
        "Matthew 24:29",
        "Joel 2:31",
        "Revelation 6:12",
        "Revelation 16:8-9"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Idolatry or false worship (condemnation of sun cults)",
      "basis": [
        "Deuteronomy 4:19",
        "2 Kings 23:5",
        "Ezekiel 8:16"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "Christian interpreters most consistently identify the sun with Christ via Malachi's 'Sun of Righteousness' and related light/glory texts; other readings are context-dependent and do not displace the Christological primacy in traditional teaching and symbolism."
}
